      "tutorial.slide2.row1": "\u0427\u0442\u043E\u0431\u044B \u043F\u043E\u043C\u043E\u0447\u044C \u0432\u0430\u043C, \u0432\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u043D\u0430\u043D\u0438\u043C\u0430\u0442\u044C \u044E\u043D\u0438\u0442\u043E\u0432 \u0441\u043E \u0432\u0441\u0435\u0445 \u0443\u0433\u043E\u043B\u043A\u043E\u0432 \u0433\u0430\u043B\u0430\u043A\u0442\u0438\u043A\u0438.",
      "tutorial.slide2.row2": "\u042E\u043D\u0438\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430\u043D\u043E\u0441\u0438\u0442\u044C \u0443\u0440\u043E\u043D, \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044C \u0438\u043B\u0438 \u0438\u0441\u0446\u0435\u043B\u044F\u0442\u044C \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u044B, \u043D\u043E \u043D\u0435 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430.",
      "tutorial.slide2.row3": "\u042E\u043D\u0438\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0434\u0435\u043B\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0438\u0445 \u044E\u043D\u0438\u0442\u043E\u0432 \u0431\u044B\u0441\u0442\u0440\u0435\u0435, \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u0435\u0435 \u0438\u043B\u0438 \u0441\u0438\u043B\u044C\u043D\u0435\u0435.",
      "tutorial.slide3.row1": "\u0411\u0430\u0437\u043E\u0432\u044B\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u044E\u043D\u0438\u0442\u043E\u0432",
      "tutorial.slide3.row2": "\u041D\u0430\u043D\u043E\u0441\u0438\u0442 \u0443\u0440\u043E\u043D \u0432\u0440\u0430\u0436\u0435\u0441\u043A\u043E\u043C\u0443 \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u0443",
