      "tutorial.slide4.row2": "\u0417\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B \u043E\u0442 \u0432\u0440\u0430\u0436\u0435\u0441\u043A\u043E\u0433\u043E \u0443\u0440\u043E\u043D\u0430",
