      "tutorial.slide5.row2": "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0436\u0438\u0437\u043D\u044C \u0432\u0430\u0448\u0435\u0433\u043E \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u0430. \u041A\u0430\u0436\u0434\u044B\u0435 20 \u0438\u0441\u0446\u0435\u043B\u0435\u043D\u0438\u044F \u0443\u0431\u0438\u0440\u0430\u044E\u0442 1 \u044F\u0434.",
      "tutorial.slide6.row1": "\u0411\u0430\u0437\u043E\u0432\u044B\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u044E\u043D\u0438\u0442\u043E\u0432",
      "tutorial.slide6.row2": "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0436\u0438\u0437\u043D\u044C \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u0435\u043A\u0443\u043D\u0434\u0443.",
      "tutorial.slide7.row1": "\u0411\u0430\u0437\u043E\u0432\u044B\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u044E\u043D\u0438\u0442\u043E\u0432",
      "tutorial.slide7.row2": "\u041D\u0430\u043D\u043E\u0441\u0438\u0442 \u0443\u0440\u043E\u043D \u0432\u0440\u0430\u0436\u0435\u0441\u043A\u043E\u043C\u0443 \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u0443 \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u0435\u043A\u0443\u043D\u0434\u0443. \u0418\u0433\u043D\u043E\u0440\u0438\u0440\u0443\u0435\u0442 \u0449\u0438\u0442.",
      "tutorial.slide8.row1": "\u041F\u0440\u043E\u0434\u0432\u0438\u043D\u0443\u0442\u044B\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438",
