      "tutorial.slide8.row3": "\u0417\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u043F\u0435\u0440\u0435\u0437\u0430\u0440\u044F\u0434\u043A\u0443 \u044E\u043D\u0438\u0442\u0430 \u0443\u043C\u0435\u043D\u044C\u0448\u0430\u0442\u044C\u0441\u044F \u0432 \u0434\u0432\u0430 \u0440\u0430\u0437\u0430 \u0431\u044B\u0441\u0442\u0440\u0435\u0435.",
      "tutorial.slide8.row4": "\u0417\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u043F\u0435\u0440\u0435\u0437\u0430\u0440\u044F\u0434\u043A\u0443 \u0443\u043C\u0435\u043D\u044C\u0448\u0430\u0442\u044C\u0441\u044F \u0432 \u0434\u0432\u0430 \u0440\u0430\u0437\u0430 \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u0435\u0435.",
      "tutorial.slide8.row5": "\u0423\u043C\u0435\u043D\u044C\u0448\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0435 \u0432\u0440\u0435\u043C\u044F \u043F\u0435\u0440\u0435\u0437\u0430\u0440\u044F\u0434\u043A\u0438.",
      "tutorial.slide8.row6": "\u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u0438\u043B\u0443 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0431\u0438\u0442\u0432\u044B.",
      "tutorial.slide8.row7": "\u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u0438\u043B\u0443 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u043D\u0430\u0432\u0441\u0435\u0433\u0434\u0430.",
      "tutorial.slide8.row8": "\u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0448\u0430\u043D\u0441 \u043D\u0430\u043D\u0435\u0441\u0442\u0438 \u0434\u0432\u043E\u0439\u043D\u0443\u044E \u0441\u0438\u043B\u0443 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u0438.",
