function createBackgroundOverlay(config = {}) {
  const scene = getCurrentScene();
  const { color, alpha, interactive } = { ...DEFAULT_CONFIG2, ...config };
  const rectangle = scene.add.rectangle(
    MIDDLE_SCREEN_X,
    MIDDLE_SCREEN_Y,
    SCREEN_WIDTH,
    SCREEN_HEIGHT,
    color,
    alpha
  );
  if (interactive) {
    rectangle.setInteractive();
  }
  rectangle.setAlpha(0);
  rectangle.setVisible(false);
  const fadeIn = (duration = DEFAULT_FADE_ANIMATION_DURATION_MS) => {
    return new Promise((resolve) => {
      rectangle.setVisible(true);
      scene.tweens.add({
        targets: rectangle,
        alpha,
        duration,
        onComplete: () => resolve()
      });
    });
  };
  const fadeOut = (duration = DEFAULT_FADE_ANIMATION_DURATION_MS) => {
    return new Promise((resolve) => {
      scene.tweens.add({
        targets: rectangle,
        alpha: 0,
        duration,
        onComplete: () => {
          rectangle.setVisible(false);
          resolve();
        }
      });
    });
  };
  const show2 = () => {
    rectangle.setVisible(true);
    rectangle.setAlpha(alpha);
  };
  const hide2 = () => {
    rectangle.setVisible(false);
    rectangle.setAlpha(0);
  };
  const destroy2 = () => {
    rectangle.destroy();
  };
  return {
    rectangle,
    fadeIn,
    fadeOut,
    show: show2,
    hide: hide2,
    destroy: destroy2
  };
}
